CREATE TABLE public.studio_device_modes (session_id uuid PRIMARY KEY, parent_id uuid NOT NULL, kid_locked boolean NOT NULL DEFAULT true, changed_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.studio_device_modes TO authenticated;
GRANT ALL ON public.studio_device_modes TO service_role;
ALTER TABLE public.studio_device_modes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own session mode" ON public.studio_device_modes FOR SELECT TO authenticated USING (parent_id=auth.uid() AND session_id=(auth.jwt()->>'session_id')::uuid);
CREATE FUNCTION public.is_parent_device() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT EXISTS(SELECT 1 FROM public.studio_device_modes WHERE parent_id=auth.uid() AND session_id=(auth.jwt()->>'session_id')::uuid AND kid_locked); $$;
REVOKE ALL ON FUNCTION public.is_parent_device() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_parent_device() TO authenticated,service_role;
REVOKE UPDATE ON public.studio_creations FROM authenticated;
REVOKE UPDATE(title,favorite,deleted_at,updated_at) ON public.studio_creations FROM authenticated;
CREATE POLICY "Parent device reads notifications" ON public.parent_notifications AS RESTRICTIVE FOR ALL TO authenticated USING(public.is_parent_device()) WITH CHECK(public.is_parent_device());
CREATE POLICY "Parent device reads audit history" ON public.studio_events AS RESTRICTIVE FOR SELECT TO authenticated USING(public.is_parent_device());
CREATE POLICY "Parent device accesses consent" ON public.parental_consents AS RESTRICTIVE FOR ALL TO authenticated USING(public.is_parent_device()) WITH CHECK(public.is_parent_device());
CREATE POLICY "Parent device manages profile" ON public.profiles AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.is_parent_device()) WITH CHECK(public.is_parent_device());
CREATE POLICY "Parent device manages children" ON public.children AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.is_parent_device()) WITH CHECK(public.is_parent_device());
CREATE POLICY "Parent device deletes children" ON public.children AS RESTRICTIVE FOR DELETE TO authenticated USING(public.is_parent_device());
CREATE POLICY "Parent device inserts children" ON public.children AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.is_parent_device());
CREATE POLICY "Parent device edits controls" ON public.child_controls AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.is_parent_device()) WITH CHECK(public.is_parent_device());
CREATE POLICY "Parent device reads ledger" ON public.glow_ledger AS RESTRICTIVE FOR SELECT TO authenticated USING(public.is_parent_device());
CREATE POLICY "Parent device changes glow settings" ON public.family_glow_settings AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.is_parent_device()) WITH CHECK(public.is_parent_device());
CREATE FUNCTION public.lock_studio_art(_id uuid,_snapshot jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.studio_creations; t public.studio_creations; BEGIN SELECT * INTO r FROM public.studio_creations WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Creation missing'; END IF; IF r.details->>'bookId' IS NOT NULL THEN SELECT * INTO t FROM public.studio_creations WHERE id=(r.details->>'bookId')::uuid FOR UPDATE; ELSE t:=r; END IF; IF t.details->'artLock' IS NULL THEN UPDATE public.studio_creations SET details=jsonb_set(coalesce(details,'{}'::jsonb),'{artLock}',_snapshot) WHERE id=t.id RETURNING * INTO t; END IF; RETURN t.details->'artLock'; END; $$;
REVOKE ALL ON FUNCTION public.lock_studio_art(uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.lock_studio_art(uuid,jsonb) TO service_role;
CREATE FUNCTION public.preserve_studio_art_lock() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.details->'artLock' IS NOT NULL THEN NEW.details=jsonb_set(coalesce(NEW.details,'{}'::jsonb),'{artLock}',OLD.details->'artLock'); END IF; IF OLD.details->'modelLock' IS NOT NULL THEN NEW.details=jsonb_set(coalesce(NEW.details,'{}'::jsonb),'{modelLock}',OLD.details->'modelLock'); END IF; RETURN NEW; END; $$;
CREATE TRIGGER preserve_studio_art BEFORE UPDATE OF details ON public.studio_creations FOR EACH ROW EXECUTE FUNCTION public.preserve_studio_art_lock();
ALTER TABLE public.drift_checks ADD COLUMN request_id uuid, ADD COLUMN creation_id uuid, ADD COLUMN model_version text, ADD COLUMN delivered boolean NOT NULL DEFAULT false, ADD COLUMN checker_available boolean NOT NULL DEFAULT true;
CREATE TABLE public.hero_portrait_provenance(path text PRIMARY KEY,parent_id uuid NOT NULL,child_id uuid NOT NULL,style_key text NOT NULL,model jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.hero_portrait_provenance TO service_role;
ALTER TABLE public.hero_portrait_provenance ENABLE ROW LEVEL SECURITY;